(function($){

	var startingPos = $(document).scrollTop();
    $(document).scroll(function(){
        startingPos = $(document).scrollTop();
    });

	if (location.hash != "") {
		var el = $("input[name='"+location.hash.replace("#","")+"']");
		if (el.length) {
			if (el.parents(".doc-center-category-content").length) {
				el.parents(".doc-center-category-content").toggle(true);
				location.hash = location.hash;
			}
		}
	}

    $("h3.docs-toggle").on('click keydown',function(){
			if (event.type == 'click' || event.key == "Enter" || event.key == " ") {
				event.preventDefault();
				$(this).next(".doc-center-category-content").stop(true).toggle(300);
				$(this).children(".fa-caret-up").toggleClass("toggled-open");
        location.hash = $(this).prev('.page_anchor').attr('name');
        $(document).scrollTop(startingPos);
			}
    });

	$(".doc-center-counter").each(function() {
		var docs = $(this).closest(".doc-center-category").find(".doc-center-entry").length;
		if (docs == 0) { docs = "No Documents"; }
		else if (docs == 1) { docs = "1 Document"; }
		else { docs = docs+" Documents"; }
		$(this).text(docs);
	});

	$("input.document-center-search").on('change', function() {
		var sea = $("input.document-center-search").val().trim().toLowerCase();
		if (sea != "") {
			$(".doc-center-entry").each(function() { 
				if ($(this).children(".doc-file-link, .doc-file-desc").filter(function() {
					if ($(this).text().toLowerCase().indexOf(sea) != -1) { return true; }
					return false;
				}).length) {
					$(this).stop(true).slideDown(300);
				} else {
					$(this).stop(true).slideUp(300);
				}
			});
		} else {
			$(".doc-center-entry").slideDown(300);
		}
	});

	$(".doc-search-submit").on('click', function() { });

})(jQuery);

$(document).ready(function(){
    $(".doc-center-counter").each(function() {
        var docText = "";
        var docs = $(this).parent().closest(".doc-center-category").find(".doc-center-entry").length;
        docText = docs+" Documents"; 
        $(this).text(docText);
    });
    $("h3.docs-toggle").on('click',function(){
        $(this).children(".fa-caret-up").toggleClass("toggled-open");
    });
});
